mapper.insert:

    SELECT /* 인서트 실행 전, 조합된 boardCode를 조회한 후 셋팅 */
           CONCAT(
                  'B_'
                  , REPLACE(#{groupCode}, 'G_BRD_','')
                  , '_'
                  , LPAD(COALESCE(MAX(CAST(SUBSTRING_INDEX(BOARD_CODE, '_', -1) AS UNSIGNED)),0)+1, 3, '0')
                  )
      FROM BOARD_MASTER
     WHERE BOARD_CODE LIKE CONCAT('B_', REPLACE(#{groupCode},'G_BRD_', ''), '_%')

INSERT INTO /* BoardMasterMapper.addBoardMaster (addBoardMaster 새로운 게시판 설정 등록) */
            BOARD_MASTER (
            BOARD_CODE
          , BOARD_NAME
          , GROUP_CODE
          , USE_YN
          , FILE_YN
          , REPLY_YN
          , TAG_YN
          , CREATE_AT
          )
     VALUES (
            #{boardCode} /* selectKey에 의해 자동 셋팅 */
          , #{boardName}
          , #{groupCode}
          , #{useYn}
          , #{fileYn}
          , #{replyYn}
          , #{tagYn}
          , CURRENT_TIMESTAMP
          )

mapper.update:
UPDATE BOARD_MASTER /* BoardMasterMapper.updateBoardMaster (게시판 설정 수정) */
   SET BOARD_NAME = #{boardName}
     , USE_YN = #{useYn}
     , FILE_YN = #{fileYn}
     , REPLY_YN = #{replyYn}
     , TAG_YN = #{tagYn}
     , UPDATE_AT = CURRENT_TIMESTAMP
 WHERE BOARD_CODE = #{boardCode}
